<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { useSemanticScope } from '../shared/useSemanticScope'
import { graphApi } from '../api/graphApi'
import { graphQueryApi } from '../api/graphQueryApi'
import { statementApi } from '../api/statementApi'
import { sourceApi } from '../api/sourceApi'
import type { SemanticEntity } from '../api/types'
import type { Change, Conflict, GraphDetail, GraphResult, Snapshot, Source, Statement } from '../api/workbenchTypes'
import EntityEditor from './EntityEditor.vue'
import GraphMigrationPanel from './GraphMigrationPanel.vue'
import SemanticGraphView from './SemanticGraphView.vue'
import SourceCapturePanel from './SourceCapturePanel.vue'
import SourceGovernancePanel from '../review/SourceGovernancePanel.vue'
import SourceChangeReviewPanel from '../review/SourceChangeReviewPanel.vue'
import StatementReviewDrawer from '../review/StatementReviewDrawer.vue'
import ConflictReviewPanel from '../review/ConflictReviewPanel.vue'
import ExtractionWizard from '../extraction/ExtractionWizard.vue'
const route = useRoute(); const { t, te } = useI18n(); const { workspace, begin } = useSemanticScope(); const graphId = computed(() => String(route.params.graphId)); const scopeKey = computed(() => `${workspace.currentWorkspaceId}:${graphId.value}`)
const canWrite = computed(() => workspace.accessLoaded && (workspace.isGlobalAdmin || workspace.isAtLeast('member'))); const canReview = computed(() => workspace.accessLoaded && (workspace.isGlobalAdmin || workspace.isAtLeast('admin')))
const detail = ref<GraphDetail | null>(null); const entities = ref<SemanticEntity[]>([]); const facts = ref<Statement[]>([]); const queue = ref<Statement[]>([]); const changes = ref<Change[]>([]); const conflicts = ref<Conflict[]>([]); const sources = ref<Source[]>([]); const snapshots = ref<Snapshot[]>([]); const graph = ref<GraphResult>({ nodes: [], edges: [], traceId: '', truncated: false }); const selectedEntity = ref(''); const selected = ref<Statement | null>(null); const evidenceId = ref<string | null>(null); const tab = ref('facts'); const error = ref(''); const busy = ref(false); const reason = ref(''); const page = ref(1); const totals = ref<Record<string, number>>({}); const generation = ref(0)
const classIris = computed(() => [...new Set(detail.value?.document?.axioms.flatMap(axiom => axiom.signatureIris) ?? [])].sort()); const total = computed(() => totals.value[tab.value] ?? 0); const paginated = computed(() => ['facts', 'queue', 'changes', 'conflicts'].includes(tab.value))
function entityName(id: string) { return entities.value.find(entity => entity.id === id)?.displayName ?? id }; function statusName(status: string) { const key = `semantic.w.states.${status}`; return te(key) ? t(key) : status }
async function load() { const run = begin(); busy.value = true; error.value = ''; evidenceId.value = null; generation.value++; try { const [d, e, f, s, sn, q, ch, co] = await Promise.all([graphQueryApi.detail(run.id, graphId.value, run.signal), graphApi.entities(run.id, graphId.value, run.signal), statementApi.list(run.id, graphId.value, 'trusted', page.value, run.signal), sourceApi.sources(run.id, graphId.value, run.signal), sourceApi.snapshots(run.id, graphId.value, run.signal), canWrite.value ? statementApi.list(run.id, graphId.value, canReview.value ? 'review' : 'mine', page.value, run.signal) : Promise.resolve({ items: [], total: 0 }), canReview.value ? statementApi.changes(run.id, graphId.value, page.value, run.signal) : Promise.resolve({ items: [], total: 0 }), canReview.value ? statementApi.conflicts(run.id, graphId.value, page.value, run.signal) : Promise.resolve({ items: [], total: 0 })]); if (!run.current()) return; detail.value = d; entities.value = e.items; facts.value = f.items; queue.value = q.items; changes.value = ch.items; conflicts.value = co.items; sources.value = s.items; snapshots.value = sn.items; totals.value = { facts: f.total ?? f.items.length, queue: q.total ?? q.items.length, changes: ch.total ?? ch.items.length, conflicts: co.total ?? co.items.length }; selectedEntity.value = e.items.some(item => item.id === selectedEntity.value) ? selectedEntity.value : e.items[0]?.id ?? ''; graph.value = selectedEntity.value ? await graphQueryApi.neighbors(run.id, graphId.value, selectedEntity.value, run.signal) : { nodes: [], edges: [], traceId: '', truncated: false } } catch (e) { if (run.current()) { error.value = (e as Error).message; detail.value = null } } finally { if (run.current()) busy.value = false } }
async function select(id: string) { selected.value = [...queue.value, ...facts.value].find(item => item.id === id) ?? null }
async function reviewChange(change: Change, action: string) { const run = begin(); busy.value = true; try { await statementApi.reviewChange(run.id, graphId.value, change, action, reason.value, run.signal); if (run.current()) { reason.value = ''; await load() } } catch (e) { if (run.current()) error.value = (e as Error).message } finally { if (run.current()) busy.value = false } }
function scrollToFocus(id: string) { void nextTick(() => globalThis.document.getElementById(id)?.scrollIntoView?.({ block: 'center', behavior: 'smooth' })) }
watch(() => [route.query?.focus, route.query?.kind, busy.value], () => { const id = String(route.query?.focus ?? ''); if (!id || busy.value) return; if (route.query?.kind === 'ENTITY') { selectedEntity.value = id; tab.value = 'entities'; scrollToFocus(`semantic-entity-${id}`) } else if (route.query?.kind === 'STATEMENT') { void select(id); tab.value = queue.value.some(item => item.id === id) ? 'queue' : 'facts' } }, { flush: 'post' }); watch(tab, () => { if (page.value !== 1) { page.value = 1; void load() } }); watch(scopeKey, () => { detail.value = null; selected.value = null; page.value = 1; void load() }, { immediate: true, flush: 'sync' })
</script>
<template><main class="semantic-workbench"><header><div><h2>{{ t('semantic.w.title') }}</h2><p class="workbench-intro">{{ t('semantic.w.workbenchHelp') }}</p><p v-if="detail" class="workbench-meta">{{ t('semantic.w.ontologyVersion') }} {{ detail.binding.ontologyVersion }} · {{ t('semantic.w.graphVersion') }} {{ detail.binding.graphVersion }} · {{ graphId }}</p></div><el-button :loading="busy" @click="load">{{ t('semantic.w.refresh') }}</el-button></header><el-alert v-if="error" :title="error" type="error" :closable="false" /><section v-if="detail" v-loading="busy"><el-alert v-if="!detail.binding.enabled" :title="t('semantic.bindingDisabled')" :closable="false" /><el-tabs v-model="tab"><el-tab-pane :label="t('semantic.migration.title')" name="migration"><GraphMigrationPanel v-if="tab === 'migration'" :graph-id="graphId" :revision-id="detail.binding.ontologyRevisionId" :graph-version="detail.binding.graphVersion" :can-manage="canReview" @changed="load" /></el-tab-pane><el-tab-pane :label="t('semantic.w.facts')" name="facts"><p>{{ t('semantic.w.businessTimeHelp') }}</p><el-select v-model="selectedEntity" :placeholder="t('semantic.w.subject')" @change="load"><el-option v-for="entity in entities" :key="entity.id" :value="entity.id" :label="entity.displayName" /></el-select><SemanticGraphView :result="graph" @select-statement="select($event.statementId)" @select-entity="selectedEntity = $event; load()" /><el-table :data="facts" :empty-text="t('semantic.w.noFacts')" @row-click="selected = $event"><el-table-column :label="t('semantic.w.subject')"><template #default="{ row }">{{ entityName(row.subjectId) }}</template></el-table-column><el-table-column :label="t('semantic.w.assertion', 'Assertion')"><template #default="{ row }"><code>{{ row.assertion?.functionalSyntax ?? '—' }}</code></template></el-table-column><el-table-column prop="revision" :label="t('semantic.w.version')" /><el-table-column :label="t('semantic.w.support')"><template #default="{ row }">{{ statusName(row.supportStatus) }}</template></el-table-column><el-table-column :label="t('semantic.w.evidence')"><template #default="{ row }"><el-button text @click.stop="selected = row">{{ t('semantic.w.viewEvidence') }} ({{ row.evidenceIds.length }})</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane v-if="canWrite && detail.binding.enabled" :label="t('semantic.w.entities')" name="entities"><EntityEditor :graph-id="graphId" :class-iris="classIris" @saved="load" /><el-table :data="entities"><el-table-column :label="t('semantic.w.name')"><template #default="{ row }"><span :id="`semantic-entity-${row.id}`">{{ row.displayName }}</span></template></el-table-column><el-table-column :label="t('semantic.w.iri')"><template #default="{ row }"><code>{{ row.iri }}</code></template></el-table-column><el-table-column :label="t('semantic.w.type')"><template #default="{ row }">{{ (row.assertedTypes ?? []).join(', ') }}</template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="t('semantic.w.sources')" name="sources"><SourceCapturePanel v-if="canWrite && detail.binding.enabled" :graph-id="graphId" :knowledge-base-id="detail.binding.knowledgeBaseId" @saved="load" /><SourceGovernancePanel :graph-id="graphId" :sources="sources" :snapshots="snapshots" :can-review="canReview" @saved="load" /></el-tab-pane><el-tab-pane :label="t('semantic.w.sourceChanges')" name="sourceChanges"><SourceChangeReviewPanel v-if="tab === 'sourceChanges' && detail.binding.enabled" :graph-id="graphId" :graph-version="detail.binding.graphVersion" :can-scan="canWrite" :can-review="canReview" @changed="load" /></el-tab-pane><el-tab-pane v-if="canWrite && detail.binding.enabled" :label="t('semantic.extraction.title')" name="extraction"><ExtractionWizard v-if="tab === 'extraction'" :graph-id="graphId" :knowledge-base-id="detail.binding.knowledgeBaseId" :document="detail.document" :entities="entities" @submitted="tab = 'queue'; load()" /></el-tab-pane><el-tab-pane v-if="canWrite" :label="t('semantic.w.queue')" name="queue"><el-table :data="queue" :empty-text="t('semantic.w.noCandidates')" @row-click="selected = $event"><el-table-column :label="t('semantic.w.subject')"><template #default="{ row }">{{ entityName(row.subjectId) }}</template></el-table-column><el-table-column :label="t('semantic.w.assertion', 'Assertion')"><template #default="{ row }"><code>{{ row.assertion?.functionalSyntax ?? '—' }}</code></template></el-table-column><el-table-column prop="reviewStatus" :label="t('semantic.w.status')" /><el-table-column prop="revision" :label="t('semantic.w.version')" /></el-table></el-tab-pane><el-tab-pane v-if="canReview" :label="t('semantic.w.changes')" name="changes"><el-input v-model="reason" :placeholder="t('semantic.w.reason')" /><el-card v-for="change in changes" :id="`semantic-change-${change.id}`" :key="change.id"><p>{{ statusName(change.status) }} · r{{ change.expectedRevision }}</p><code>{{ change.content.assertionText }}</code><div v-if="change.status === 'PENDING'"><el-button :disabled="busy || !reason.trim()" @click="reviewChange(change, 'ACCEPT')">{{ t('semantic.w.accept') }}</el-button><el-button :disabled="busy || !reason.trim()" @click="reviewChange(change, 'REJECT')">{{ t('semantic.w.reject') }}</el-button></div></el-card></el-tab-pane><el-tab-pane v-if="canReview" :label="t('semantic.w.conflicts')" name="conflicts"><ConflictReviewPanel :graph-id="graphId" :conflicts="conflicts" :statements="[...facts, ...queue]" :entities="entities" @saved="load" @select="select" @evidence="evidenceId = $event" /></el-tab-pane></el-tabs><el-pagination v-if="paginated && total > 100" v-model:current-page="page" :page-size="100" :total="total" layout="prev, pager, next" @current-change="load" /><StatementReviewDrawer :graph-id="graphId" :statement="selected" :can-review="canReview" @close="selected = null" @saved="load" @evidence="evidenceId = $event" /></section></main></template>
<style scoped>.workbench-meta { font-size: 12px; overflow-wrap: anywhere; }.semantic-focus-target { outline: 2px solid var(--el-color-primary); }.semantic-workbench { box-sizing: border-box; padding: 24px; width: 100%; min-width: 0; max-width: 1500px; margin: 0 auto; overflow: hidden; } header { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin-bottom: 12px; } header > div { min-width: 0; } header h2 { margin: 0; font-size: 22px; font-weight: 600; line-height: 1.4; } header p { color: var(--mc-text-secondary); overflow-wrap: anywhere; margin-top: 6px; } section { min-width: 0; } :deep(.el-card) { margin: 12px 0; } :deep(.el-select) { min-width: 0; width: 100%; max-width: 420px; }</style>
